CREATE TABLE IF NOT EXISTS economic_model_change_sandboxes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), calibration_review_id uuid NOT NULL, profile_id uuid NOT NULL, status text NOT NULL DEFAULT 'created', baseline_score numeric(5,2), proposed_score numeric(5,2), simulated_delta numeric(6,2), test_result text, production_applied boolean NOT NULL DEFAULT false, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS economic_model_change_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sandbox_id uuid NOT NULL, profile_id uuid NOT NULL, event_type text NOT NULL, actor_id text NOT NULL, from_status text, to_status text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_model_sandbox_profile ON economic_model_change_sandboxes(profile_id,created_at DESC);